import { useEffect, useState } from 'react';
import { Activity, AlertTriangle, BrainCircuit, Check, ChevronRight, CircleDollarSign, Database, FileClock, Gauge, LockKeyhole, Network, Plus, RefreshCw, Scale, ShieldCheck, Sparkles, Target, TrendingUp, WifiOff, X } from 'lucide-react';
import { api, del, post } from '../api';
import type { Dashboard, PendingChange, Position, Strategy, StrategyConfig, View } from '../types';

interface Shared { dashboard: Dashboard; refresh: () => Promise<void>; notify: (message: string, tone?: string) => void }
const money = (value: number, digits = 2) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: digits }).format(value);
const percent = (value: number) => `${value >= 0 ? '+' : ''}${value.toFixed(2)}%`;
const dateTime = (value: unknown) => typeof value === 'string' ? new Date(value).toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : '—';
const text = (value: unknown) => typeof value === 'string' ? value : value === null || value === undefined ? '—' : String(value);

export function OverviewView({ dashboard, refresh, notify, openChat, navigate }: Shared & { openChat: () => void; navigate: (view: View) => void }) {
  const [tradeOpen, setTradeOpen] = useState(false);
  const positive = dashboard.metrics.totalPnl >= 0;
  return <div className="page overview-page">
    <section className="welcome-row"><div><p className="eyebrow">AUTONOMOUS CONTROL PLANE</p><h2>Good {new Date().getHours() < 12 ? 'morning' : 'afternoon'}, Operator.</h2><p>{dashboard.globalPause ? 'Autonomy is paused. The system remains observable.' : 'All configured services are reporting. Authority gates remain enforced.'}</p></div><div className="welcome-actions"><button className="button secondary" onClick={openChat}><BrainCircuit size={16} /> Ask manager</button><button className="button primary" onClick={() => setTradeOpen(true)} disabled={!dashboard.simulated}><Sparkles size={16} /> Simulation lab</button></div></section>
    <section className="metric-grid">
      <Metric label="Portfolio equity" value={money(dashboard.metrics.equity)} meta={`${positive ? '+' : ''}${money(dashboard.metrics.totalPnl)} designated P/L`} tone={positive ? 'positive' : 'negative'} icon={CircleDollarSign} />
      <Metric label="Available virtual cash" value={money(dashboard.metrics.cash)} meta={`${money(dashboard.metrics.exposure)} deployed`} icon={Database} />
      <Metric label="Unrealized P/L" value={money(dashboard.metrics.unrealizedPnl)} meta={`${money(dashboard.metrics.realizedPnl)} realized`} tone={dashboard.metrics.unrealizedPnl >= 0 ? 'positive' : 'negative'} icon={TrendingUp} />
      <Metric label="Account exposure" value={`${dashboard.metrics.exposurePercent.toFixed(1)}%`} meta={`${dashboard.risk.config.maxTotalExposurePercent}% hard limit`} tone={dashboard.metrics.exposurePercent > Number(dashboard.risk.config.maxTotalExposurePercent) * .8 ? 'warning' : 'positive'} icon={Gauge} />
    </section>
    <section className="overview-grid">
      <article className="panel equity-panel"><PanelHead eyebrow="PORTFOLIO EQUITY" title={money(dashboard.metrics.equity)} action={<button className="text-button" onClick={() => navigate('performance')}>Full analytics <ChevronRight /></button>} /><EquityMiniChart base={dashboard.metrics.equity - dashboard.metrics.totalPnl} current={dashboard.metrics.equity} /><footer><span><i className="legend-dot account" />Account</span><span><i className="legend-dot benchmark" />Illustrative benchmark</span><small>30-day simulated view</small></footer></article>
      <article className="panel risk-snapshot"><PanelHead eyebrow="GLOBAL RISK" title="Within configured limits" action={<span className="health-label"><ShieldCheck /> ENFORCED</span>} />
        <UtilizationRow label="Exposure" current={dashboard.metrics.exposure} limit={dashboard.risk.utilization.exposure.limit ?? 1} format="money" />
        <UtilizationRow label="Daily loss" current={dashboard.risk.utilization.dailyLoss.current} limit={dashboard.risk.utilization.dailyLoss.limit ?? 1} format="money" />
        <UtilizationRow label="Cash reserve" current={dashboard.risk.utilization.cashReserve.current} limit={dashboard.risk.utilization.cashReserve.minimum ?? 1} format="reserve" />
        <button className="panel-link" onClick={() => navigate('risk')}>Inspect all hard limits <ChevronRight /></button>
      </article>
    </section>
    <section className="section-heading"><div><p className="eyebrow">STRATEGY DESK</p><h2>Three mandates. One guarded account.</h2></div><button className="text-button" onClick={() => navigate('strategies')}>Configure strategies <ChevronRight /></button></section>
    <div className="strategy-card-grid">{dashboard.strategies.map((strategy, index) => <StrategyCard key={strategy.id} strategy={strategy} index={index} positions={dashboard.positions.filter((position) => position.strategyId === strategy.id)} />)}</div>
    <section className="lower-grid">
      <article className="panel activity-panel"><PanelHead eyebrow="LIVE ACTIVITY" title="Decision + control feed" action={<button className="text-button" onClick={() => navigate('activity')}>Audit log <ChevronRight /></button>} /><div className="feed">{dashboard.recentDecisions.slice(0, 4).map((decision, index) => <FeedRow key={text(decision.id) || index} time={decision.createdAt} type="DECISION" tone="cyan" body={`${text(decision.symbol)} · ${text(decision.rationale)}`} result={`${text(decision.action)} ${typeof decision.confidence === 'number' ? `· ${decision.confidence.toFixed(2)}` : ''}`} />)}{dashboard.recentRisks.slice(0, 2).map((risk, index) => <FeedRow key={text(risk.id) || index} time={risk.createdAt} type="RISK" tone="amber" body={text(risk.message)} result={text(risk.severity)} />)}{!dashboard.recentDecisions.length && !dashboard.recentRisks.length && <Empty icon={Activity} title="No activity yet" body="Run a simulation analysis or submit a simulated proposal." />}</div></article>
      <article className="panel health-panel"><PanelHead eyebrow="SYSTEM HEALTH" title={dashboard.health.status === 'healthy' ? 'All systems nominal' : 'Attention required'} action={<span className={`system-led ${dashboard.health.status}`} />}/><div className="health-list">{Object.entries(dashboard.health.checks).map(([name, check]) => <div key={name}><span className={check.ok ? 'ok' : 'bad'}>{check.ok ? <Check /> : <X />}</span><div><b>{name}</b><small>{check.message}</small></div><i>{check.ok ? 'READY' : 'FAULT'}</i></div>)}</div></article>
    </section>
    {tradeOpen && <SimulationLab dashboard={dashboard} close={() => setTradeOpen(false)} refresh={refresh} notify={notify} />}
  </div>;
}

function Metric({ label, value, meta, tone = '', icon: Icon }: { label: string; value: string; meta: string; tone?: string; icon: typeof Activity }) { return <article className="metric-card"><div><span>{label}</span><Icon size={17} /></div><strong>{value}</strong><small className={tone}>{meta}</small></article>; }
function PanelHead({ eyebrow, title, action }: { eyebrow: string; title: string; action?: React.ReactNode }) { return <header className="panel-head"><div><p className="eyebrow">{eyebrow}</p><h3>{title}</h3></div>{action}</header>; }
function EquityMiniChart({ base, current }: { base: number; current: number }) { const values = [base, base * .997, base * 1.002, base * 1.001, base * 1.006, base * 1.004, base * 1.009, current * .996, current]; const min = Math.min(...values) * .998; const max = Math.max(...values) * 1.002; return <div className="equity-mini"><div className="chart-grid" />{values.map((value, index) => <i key={index} style={{ height: `${Math.max(8, (value - min) / (max - min) * 92)}%` }}><span /></i>)}</div>; }
function UtilizationRow({ label, current, limit, format }: { label: string; current: number; limit: number; format: 'money' | 'reserve' }) { const ratio = format === 'reserve' ? Math.min(1, current / limit) : Math.min(1, current / limit); const warning = format !== 'reserve' && ratio > .75; return <div className="util-row"><div><span>{label}</span><b>{money(current, 0)} <small>/ {format === 'reserve' ? `min ${money(limit, 0)}` : money(limit, 0)}</small></b></div><div><i className={warning ? 'warn' : ''} style={{ width: `${ratio * 100}%` }} /></div></div>; }
function StrategyCard({ strategy, index, positions }: { strategy: Strategy; index: number; positions: Position[] }) { return <article className={`strategy-card tone-${index}`}><header><span className="strategy-monogram">{index === 0 ? 'D' : index === 1 ? 'G' : 'L'}</span><span className={`agent-status ${strategy.status.toLowerCase()}`}><i />{strategy.status}</span></header><h3>{strategy.name}</h3><p>{money(strategy.allocationAmount, 0)} allocation · v{strategy.version}</p><div className="strategy-stats"><div><span>Available</span><b>{money(strategy.cash, 0)}</b></div><div><span>Today</span><b className={(strategy.unrealizedPnl ?? 0) >= 0 ? 'positive' : 'negative'}>{money((strategy.realizedPnl ?? 0) + (strategy.unrealizedPnl ?? 0))}</b></div></div><footer><span>{positions.length} positions</span><span>{positions.slice(0, 3).map((position) => position.symbol).join(' · ') || 'No holdings'}</span></footer></article>; }
function FeedRow({ time, type, tone, body, result }: { time: unknown; type: string; tone: string; body: string; result: string }) { return <div className="feed-row"><time>{dateTime(time).split(',').at(-1)}</time><span className={`feed-type ${tone}`}>{type}</span><p>{body}</p><b>{result}</b></div>; }
function Empty({ icon: Icon, title, body }: { icon: typeof Activity; title: string; body: string }) { return <div className="empty"><Icon /><b>{title}</b><p>{body}</p></div>; }

function SimulationLab({ dashboard, close, refresh, notify }: Shared & { close: () => void }) {
  const first = dashboard.strategies[0]; const [strategyId, setStrategyId] = useState(first?.id ?? ''); const [symbol, setSymbol] = useState('RKLB'); const [side, setSide] = useState<'BUY' | 'SELL'>('BUY'); const [quantity, setQuantity] = useState(1); const [price, setPrice] = useState(47.18); const [busy, setBusy] = useState(false); const [result, setResult] = useState<Record<string, unknown> | null>(null);
  const submit = async () => { setBusy(true); try { const proposal = { strategyId, symbol, action: side, orderIntent: { side, quantity, orderType: 'MARKET', timeInForce: 'DAY', assetType: 'EQUITY' }, confidence: .72, thesis: 'Operator-authored simulation proposal for validating the deterministic execution pipeline.', timeHorizon: 'Simulation session', riskFactors: ['Synthetic market price', 'No live execution'], invalidationConditions: ['Risk rejection', 'Operator cancellation'], requestedCapital: quantity * price, requiresImmediateAction: false, marketPrice: price, marketDataAsOf: new Date().toISOString(), sector: symbol === 'NVDA' ? 'Technology' : 'Unknown', source: 'USER' }; const response = await post<Record<string, unknown>>('/api/trades/execute', { proposal, idempotencyKey: `ui-${crypto.randomUUID()}` }); setResult(response); notify(text(response.status) === 'REJECTED' ? 'Proposal rejected by deterministic risk.' : 'Simulated fill committed to the virtual ledger.', text(response.status) === 'REJECTED' ? 'warning' : 'success'); await refresh(); } catch (cause) { notify(cause instanceof Error ? cause.message : String(cause), 'danger'); } finally { setBusy(false); } };
  return <div className="modal-backdrop"><section className="modal lab-modal"><header><div><p className="eyebrow">SIMULATION LAB</p><h2>Route a typed proposal</h2></div><button className="icon-button" onClick={close}><X /></button></header><div className="safety-callout"><LockKeyhole /><p><b>No brokerage access.</b> This proposal still passes schema, directive, allocation, risk, freshness, reconciliation, and mode gates.</p></div><div className="form-grid"><label className="field"><span>Strategy owner</span><select value={strategyId} onChange={(event) => setStrategyId(event.target.value)}>{dashboard.strategies.map((strategy) => <option key={strategy.id} value={strategy.id}>{strategy.name} · {money(strategy.cash, 0)} cash</option>)}</select></label><label className="field"><span>Symbol</span><input value={symbol} onChange={(event) => setSymbol(event.target.value.toUpperCase())} /></label><label className="field"><span>Side</span><select value={side} onChange={(event) => setSide(event.target.value as 'BUY' | 'SELL')}><option>BUY</option><option>SELL</option></select></label><label className="field"><span>Quantity</span><input type="number" min="0.000001" value={quantity} onChange={(event) => setQuantity(Number(event.target.value))} /></label><label className="field"><span>Simulated market price</span><input type="number" min="0.01" value={price} onChange={(event) => setPrice(Number(event.target.value))} /></label><div className="order-notional"><span>Order notional</span><strong>{money(quantity * price)}</strong></div></div>{result && <div className={`execution-result ${text(result.status).toLowerCase()}`}><b>{text(result.status)}</b><span>Order {text(result.orderId)}</span></div>}<footer><button className="button secondary" onClick={close}>Close</button><button className="button primary" disabled={busy || !strategyId || !symbol} onClick={() => void submit()}>{busy ? 'Evaluating…' : 'Run guarded simulation'} <ChevronRight /></button></footer></section></div>;
}

export function AgentsView({ dashboard, refresh, notify }: Shared) {
  const [agents, setAgents] = useState<Array<Record<string, unknown>>>([]); const [selected, setSelected] = useState(dashboard.strategies[0]?.id ?? ''); const [symbol, setSymbol] = useState('NVDA'); const [useCodex, setUseCodex] = useState(false); const [busy, setBusy] = useState(false); const [decision, setDecision] = useState<Record<string, unknown> | null>(null);
  const load = async () => { const response = await api<{ agents: Array<Record<string, unknown>> }>('/api/agents/status'); setAgents(response.agents); };
  useEffect(() => { void load(); }, []);
  const analyze = async () => { setBusy(true); try { const result = await post<Record<string, unknown>>(`/api/agents/${selected}/analyze`, { symbol, useCodex }); setDecision(result); notify(useCodex ? 'Codex analysis completed.' : 'Safe simulated agent analysis completed.'); await Promise.all([load(), refresh()]); } catch (cause) { notify(cause instanceof Error ? cause.message : String(cause), 'danger'); } finally { setBusy(false); } };
  return <div className="page"><PageTitle eyebrow="AGENT OBSERVABILITY" title="Reasoning desks" body="Live state and concise audit summaries—never hidden chain-of-thought." /><div className="agent-grid">{agents.map((agent, index) => <article className={`panel agent-card tone-${index}`} key={text(agent.id)}><header><span className="strategy-monogram">{index === 0 ? 'D' : index === 1 ? 'G' : 'L'}</span><span className={`agent-status ${text(agent.status).toLowerCase()}`}><i />{text(agent.status)}</span></header><h3>{text(agent.name)}</h3><p>{text(agent.currentTask)}</p><dl><div><dt>Last successful run</dt><dd>{dateTime(agent.lastSuccessfulRun)}</dd></div><div><dt>Average duration</dt><dd>{typeof agent.averageRunDurationMs === 'number' ? `${Math.round(agent.averageRunDurationMs / 1000)}s` : '—'}</dd></div><div><dt>Recent failures</dt><dd>{text(agent.recentFailures)}</dd></div></dl><div className="last-decision"><span>LAST DECISION</span><p>{agent.lastDecision && typeof agent.lastDecision === 'object' ? `${text((agent.lastDecision as Record<string, unknown>).symbol)} · ${text((agent.lastDecision as Record<string, unknown>).rationale)}` : 'No decision recorded'}</p></div></article>)}</div><section className="panel analysis-console"><PanelHead eyebrow="ANALYSIS CONSOLE" title="Trigger a controlled agent review" /><div className="analysis-form"><label className="field"><span>Logical agent</span><select value={selected} onChange={(event) => setSelected(event.target.value)}>{dashboard.strategies.map((strategy) => <option value={strategy.id} key={strategy.id}>{strategy.name}</option>)}</select></label><label className="field"><span>Symbol</span><input value={symbol} onChange={(event) => setSymbol(event.target.value.toUpperCase())} /></label><label className="toggle-row compact-toggle"><input type="checkbox" checked={useCodex} onChange={(event) => setUseCodex(event.target.checked)} /><span><b>Invoke Codex</b><small>Off uses deterministic demo reasoning.</small></span></label><button className="button primary" disabled={busy} onClick={() => void analyze()}>{busy ? <RefreshCw className="spin" /> : <BrainCircuit />} {busy ? 'Analyzing…' : 'Run analysis'}</button></div>{decision && <DecisionCard decision={decision} />}</section></div>;
}

function DecisionCard({ decision }: { decision: Record<string, unknown> }) { const proposal = decision.proposal as Record<string, unknown> | undefined; return <article className="decision-card"><header><span>STRUCTURED AGENT DECISION</span><b>{text(proposal?.action)} · {typeof proposal?.confidence === 'number' ? proposal.confidence.toFixed(2) : '—'}</b></header><h3>{text(proposal?.symbol)} · {text(proposal?.timeHorizon)}</h3><p>{text(proposal?.thesis)}</p><div><span><b>Rationale</b>{text(decision.rationale)}</span><span><b>Execution</b>No order was created. Analysis is advisory until routed through the guarded pipeline.</span></div></article>; }

export function StrategiesView({ dashboard, refresh, notify }: Shared) {
  const [editing, setEditing] = useState<Strategy | null>(null); const [versions, setVersions] = useState<Record<string, unknown>[]>([]); const [pending, setPending] = useState<PendingChange | null>(null);
  const open = async (strategy: Strategy) => { setEditing(structuredClone(strategy)); const response = await api<{ versions: Array<Record<string, unknown>> }>(`/api/strategies/${strategy.id}/versions`); setVersions(response.versions); };
  const save = async () => { if (!editing) return; try { const response = await post<{ change: PendingChange }>(`/api/strategies/${editing.id}/change`, { config: editing.config, reason: 'Operator confirmed strategy editor changes' }); setPending(response.change); } catch (cause) { notify(cause instanceof Error ? cause.message : String(cause), 'danger'); } };
  const confirm = async () => { if (!pending) return; await post(`/api/changes/${pending.id}/confirm`, {}); notify('Strategy version committed and audit logged.'); setPending(null); setEditing(null); await refresh(); };
  return <div className="page"><PageTitle eyebrow="VERSIONED STRATEGY CONTROL" title="Mandates + hard limits" body="Edits become reviewable changes, then immutable versions. Example defaults are not financial recommendations." /><div className="strategy-table">{dashboard.strategies.map((strategy, index) => <article className="panel strategy-row" key={strategy.id}><span className={`strategy-monogram tone-${index}`}>{index === 0 ? 'D' : index === 1 ? 'G' : 'L'}</span><div className="strategy-row-main"><h3>{strategy.name}</h3><p>{strategy.kind.replaceAll('_', ' ')} · Strategy v{strategy.version}</p></div><dl><div><dt>Allocation</dt><dd>{money(strategy.allocationAmount, 0)}</dd></div><div><dt>Position cap</dt><dd>{strategy.config.maxPositionPercent}%</dd></div><div><dt>Daily loss</dt><dd>{strategy.config.maxDailyLossPercent}%</dd></div><div><dt>Open positions</dt><dd>{strategy.positionCount ?? 0} / {strategy.config.maxSimultaneousPositions}</dd></div></dl><span className={`agent-status ${strategy.enabled ? 'idle' : 'paused'}`}><i />{strategy.enabled ? 'ENABLED' : 'PAUSED'}</span><button className="button secondary" onClick={() => void open(strategy)}>Configure <ChevronRight /></button></article>)}</div>{editing && <StrategyEditor strategy={editing} setStrategy={setEditing} versions={versions} close={() => setEditing(null)} save={() => void save()} onRevert={async (version) => { const response = await post<{ change: PendingChange }>(`/api/strategies/${editing.id}/revert`, { version }); setPending(response.change); }} />}{pending && <ConfirmChange change={pending} confirm={() => void confirm()} cancel={() => setPending(null)} />}</div>;
}

function StrategyEditor({ strategy, setStrategy, versions, close, save, onRevert }: { strategy: Strategy; setStrategy: (strategy: Strategy) => void; versions: Array<Record<string, unknown>>; close: () => void; save: () => void; onRevert: (version: number) => Promise<void> }) {
  const update = (key: keyof StrategyConfig, value: unknown) => setStrategy({ ...strategy, config: { ...strategy.config, [key]: value } });
  const updateScanner = (key: keyof StrategyConfig['scanner'], value: number) => update('scanner', { ...strategy.config.scanner, [key]: value });
  const updateSchedule = (key: keyof StrategyConfig['schedule'], value: string | boolean) => update('schedule', { ...strategy.config.schedule, [key]: value });
  return <div className="drawer-backdrop"><section className="strategy-drawer"><header><div><p className="eyebrow">STRATEGY v{strategy.version}</p><h2>{strategy.name}</h2></div><button className="icon-button" onClick={close}><X /></button></header><div className="drawer-body"><EditorGroup title="Capital allocation"><NumberField label="Allocation amount" value={strategy.config.allocationAmount} prefix="$" onChange={(value) => update('allocationAmount', value)} /><NumberField label="Target cash reserve" value={strategy.config.targetCashReservePercent} suffix="%" onChange={(value) => update('targetCashReservePercent', value)} /></EditorGroup><EditorGroup title="Position + exposure limits"><NumberField label="Maximum individual position" value={strategy.config.maxPositionPercent} suffix="%" onChange={(value) => update('maxPositionPercent', value)} /><NumberField label="Maximum sector exposure" value={strategy.config.maxSectorExposurePercent} suffix="%" onChange={(value) => update('maxSectorExposurePercent', value)} /><NumberField label="Simultaneous positions" value={strategy.config.maxSimultaneousPositions} onChange={(value) => update('maxSimultaneousPositions', value)} /></EditorGroup><EditorGroup title="Loss + turnover limits"><NumberField label="Maximum daily loss" value={strategy.config.maxDailyLossPercent} suffix="%" onChange={(value) => update('maxDailyLossPercent', value)} /><NumberField label="Maximum drawdown" value={strategy.config.maxDrawdownPercent} suffix="%" onChange={(value) => update('maxDrawdownPercent', value)} /><NumberField label="Maximum trades / day" value={strategy.config.maxTradesPerDay} onChange={(value) => update('maxTradesPerDay', value)} /><NumberField label="Turnover limit" value={strategy.config.turnoverLimitPercent} suffix="%" onChange={(value) => update('turnoverLimitPercent', value)} /></EditorGroup><EditorGroup title="Holding rules"><label className="toggle-row"><input type="checkbox" checked={strategy.config.overnightHoldingsAllowed} onChange={(event) => update('overnightHoldingsAllowed', event.target.checked)} /><span><b>Overnight holdings allowed</b><small>Disabled by default for the Day Trader example.</small></span></label><NumberField label="Minimum intended holding days" value={strategy.config.minimumHoldingDays} onChange={(value) => update('minimumHoldingDays', value)} /></EditorGroup><EditorGroup title="Scanner rules"><NumberField label="Minimum price" value={strategy.config.scanner.minPrice} prefix="$" onChange={(value) => updateScanner('minPrice', value)} /><NumberField label="Maximum price" value={strategy.config.scanner.maxPrice} prefix="$" onChange={(value) => updateScanner('maxPrice', value)} /><NumberField label="Minimum relative volume" value={strategy.config.scanner.minRelativeVolume} suffix="×" onChange={(value) => updateScanner('minRelativeVolume', value)} /><NumberField label="Minimum move" value={strategy.config.scanner.minMovePercent} suffix="%" onChange={(value) => updateScanner('minMovePercent', value)} /><NumberField label="Maximum spread" value={strategy.config.scanner.maxSpreadPercent} suffix="%" onChange={(value) => updateScanner('maxSpreadPercent', value)} /><NumberField label="Candidate limit" value={strategy.config.scanner.limit} onChange={(value) => updateScanner('limit', value)} /></EditorGroup><EditorGroup title="Schedule"><label className="field"><span>Timezone</span><input value={strategy.config.schedule.timezone} onChange={(event) => updateSchedule('timezone', event.target.value)} /></label><label className="field"><span>Review cron · minute hour day month weekday</span><input value={strategy.config.schedule.reviewCron} onChange={(event) => updateSchedule('reviewCron', event.target.value)} /></label><label className="toggle-row"><input type="checkbox" checked={strategy.config.schedule.marketOpenReview} onChange={(event) => updateSchedule('marketOpenReview', event.target.checked)} /><span><b>Market-open review</b><small>Uses provider market status rather than weekday assumptions.</small></span></label><label className="toggle-row"><input type="checkbox" checked={strategy.config.schedule.preCloseReview} onChange={(event) => updateSchedule('preCloseReview', event.target.checked)} /><span><b>Pre-close review</b><small>Queue a review before configured market close.</small></span></label></EditorGroup><EditorGroup title="Agent guidance"><label className="field"><span>Audit-visible guidance</span><textarea value={strategy.config.agentGuidance} onChange={(event) => update('agentGuidance', event.target.value)} rows={5} /></label></EditorGroup><EditorGroup title="Version history"><div className="version-list">{versions.map((version) => <div key={text(version.id)}><span><b>v{text(version.version)}</b>{text(version.reason)}</span><time>{dateTime(version.createdAt)}</time>{Number(version.version) !== strategy.version && <button className="text-button" onClick={() => void onRevert(Number(version.version))}>Propose restore</button>}</div>)}</div></EditorGroup></div><footer><span>Unsaved changes require explicit confirmation.</span><div><button className="button secondary" onClick={close}>Discard</button><button className="button primary" onClick={save}>Review change</button></div></footer></section></div>;
}
function EditorGroup({ title, children }: { title: string; children: React.ReactNode }) { return <section className="editor-group"><h3>{title}</h3><div>{children}</div></section>; }
function NumberField({ label, value, onChange, prefix, suffix }: { label: string; value: number; onChange: (value: number) => void; prefix?: string | undefined; suffix?: string | undefined }) { return <label className="field number-field"><span>{label}</span><div>{prefix && <i>{prefix}</i>}<input type="number" min="0" value={value} onChange={(event) => onChange(Number(event.target.value))} />{suffix && <i>{suffix}</i>}</div></label>; }
function ConfirmChange({ change, confirm, cancel }: { change: PendingChange; confirm: () => void; cancel: () => void }) { return <div className="modal-backdrop"><section className="modal confirm-modal"><span className="confirm-icon"><ShieldCheck /></span><p className="eyebrow">CONFIRM MATERIAL CHANGE</p><h2>{change.reason}</h2><p>This will create an audit event and a new immutable configuration version where applicable.</p><div className="change-contract"><span>Change ID</span><code>{change.id}</code><span>Expires</span><b>{dateTime(change.expiresAt)}</b></div><footer><button className="button secondary" onClick={cancel}>Cancel</button><button className="button primary" onClick={confirm}>Confirm + commit</button></footer></section></div>; }

export function WatchlistsView({ dashboard, refresh, notify }: Shared) {
  const [data, setData] = useState<{ watchlists: Array<Record<string, unknown>>; directives: Array<Record<string, unknown>> }>({ watchlists: [], directives: [] });
  const [scanner, setScanner] = useState<{ candidates: Array<Record<string, unknown>>; source: string; simulated: boolean }>({ candidates: [], source: '', simulated: true });
  const [strategyId, setStrategyId] = useState(dashboard.strategies[0]?.id ?? ''); const [symbol, setSymbol] = useState('RKLB'); const [researchOnly, setResearchOnly] = useState(true); const [reason, setReason] = useState('Research candidate; no trading authorization.');
  const load = async () => { const [strategyData, scannerData] = await Promise.all([api<typeof data>('/api/strategies'), api<typeof scanner>(`/api/scanner?strategyId=${encodeURIComponent(strategyId)}`)]); setData(strategyData); setScanner(scannerData); };
  useEffect(() => { void load(); }, [strategyId]);
  const add = async () => { await post('/api/watchlists', { strategyId, symbol, researchOnly, notes: reason }); notify(`${symbol} added${researchOnly ? ' as research-only' : ''}.`); await Promise.all([load(), refresh()]); };
  const currentStrategy = dashboard.strategies.find((strategy) => strategy.id === strategyId);
  return <div className="page"><PageTitle eyebrow="UNIVERSE + DIRECTIVES" title="Watchlists + scanner" body="Mechanical shortlisting, research interest, and trading permission remain intentionally separate." />
    <section className="watch-grid"><article className="panel"><PanelHead eyebrow="ADD SYMBOL" title="Strategy watchlist" /><div className="stack-form"><label className="field"><span>Strategy</span><select value={strategyId} onChange={(event) => setStrategyId(event.target.value)}>{dashboard.strategies.map((strategy) => <option value={strategy.id} key={strategy.id}>{strategy.name}</option>)}</select></label><label className="field"><span>Symbol</span><input value={symbol} onChange={(event) => setSymbol(event.target.value.toUpperCase())} /></label><label className="field"><span>Notes / directive reason</span><textarea rows={3} value={reason} onChange={(event) => setReason(event.target.value)} /></label><label className="toggle-row"><input type="checkbox" checked={researchOnly} onChange={(event) => setResearchOnly(event.target.checked)} /><span><b>Research-only</b><small>Deterministically blocks all trade proposals for this strategy and symbol.</small></span></label><button className="button primary" onClick={() => void add()}><Plus /> Add to watchlist</button></div></article><article className="panel watch-table"><PanelHead eyebrow="ACTIVE UNIVERSE" title={`${data.watchlists.length} watched symbols`} /><div className="data-table"><div className="table-head"><span>Symbol</span><span>Strategy</span><span>Permission</span><span>Notes</span></div>{data.watchlists.map((item, index) => <div key={`${text(item.strategy_id)}-${text(item.symbol)}-${index}`}><b>{text(item.symbol)}</b><span>{dashboard.strategies.find((strategy) => strategy.id === item.strategy_id)?.name ?? text(item.strategy_id)}</span><span className={Number(item.research_only) ? 'tag amber' : 'tag cyan'}>{Number(item.research_only) ? 'RESEARCH ONLY' : 'TRADING ELIGIBLE'}</span><small>{text(item.notes)}</small></div>)}</div></article></section>
    <section className="panel scanner-panel"><PanelHead eyebrow={`${scanner.simulated ? 'SIMULATED ' : ''}MARKET SCANNER · ${scanner.source}`} title={`${currentStrategy?.name ?? 'Strategy'} candidate shortlist`} action={<button className="text-button" onClick={() => void load()}><RefreshCw /> Refresh shortlist</button>} /><div className="data-table scanner-table"><div className="table-head"><span>Candidate</span><span>Reason</span><span>Score</span><span>Metrics</span><span>Permission</span><span>Latest AI evaluation</span></div>{scanner.candidates.map((candidate) => { const latest = dashboard.recentDecisions.find((decision) => decision.symbol === candidate.symbol && decision.strategyId === strategyId); const watched = data.watchlists.find((item) => item.strategy_id === strategyId && item.symbol === candidate.symbol); return <div key={text(candidate.symbol)}><b>{text(candidate.symbol)}</b><span>{text(candidate.reason)}</span><strong>{(Number(candidate.score) * 100).toFixed(0)}</strong><small>{Object.entries(candidate.metrics as Record<string, unknown>).map(([key, value]) => `${key} ${typeof value === 'number' ? value.toFixed(2) : text(value)}`).join(' · ')}</small><span className={watched && !Number(watched.research_only) ? 'tag cyan' : 'tag amber'}>{watched && !Number(watched.research_only) ? 'PERMITTED' : 'RESEARCH ONLY'}</span><small>{latest ? `${text(latest.action)} · ${Number(latest.confidence ?? 0).toFixed(2)}` : 'Not evaluated'}</small></div>; })}</div></section>
    <section className="panel directive-panel"><PanelHead eyebrow="ACTIVE DIRECTIVES" title="Higher than agent decisions" /><div className="directive-grid">{data.directives.filter((directive) => directive.active).map((directive) => <article key={text(directive.id)}><header><span className="tag amber">{text(directive.type).replaceAll('_', ' ')}</span><button className="icon-button tiny" onClick={async () => { await del(`/api/directives/${text(directive.id)}`); notify('Directive deactivated.'); await load(); }}><X /></button></header><h3>{text(directive.symbol)}</h3><p>{text(directive.reason)}</p><small>{directive.strategyId ? dashboard.strategies.find((strategy) => strategy.id === directive.strategyId)?.name : 'All strategies'} · {directive.expiresAt ? `Expires ${dateTime(directive.expiresAt)}` : 'No expiration'}</small></article>)}{!data.directives.filter((directive) => directive.active).length && <Empty icon={Target} title="No active directives" body="Add a research-only symbol to create one." />}</div></section>
  </div>;
}

export function RiskView({ dashboard, refresh, notify }: Shared) {
  const risk = dashboard.risk;
  const [editing, setEditing] = useState<Record<string, number | boolean> | null>(null);
  const [pending, setPending] = useState<PendingChange | null>(null);
  const propose = async (config: Record<string, number | boolean>) => { try { const response = await post<{ change: PendingChange }>('/api/risk/change', { config, reason: 'Operator reviewed global hard-risk limit changes' }); setEditing(null); setPending(response.change); } catch (cause) { notify(cause instanceof Error ? cause.message : String(cause), 'danger'); } };
  const confirm = async () => { if (!pending) return; await post(`/api/changes/${pending.id}/confirm`, {}); setPending(null); notify('Global hard-risk configuration committed and audited.'); await refresh(); };
  return <div className="page">
    <PageTitle eyebrow="DETERMINISTIC AUTHORITY" title="Risk control" body="Global hard limits outrank strategy limits, directives, and every agent decision." actions={<button className="button secondary" onClick={() => setEditing(structuredClone(risk.config))}><ShieldCheck /> Edit hard limits</button>} />
    <div className={`risk-state ${risk.reconciliationClear ? 'clear' : 'blocked'}`}><ShieldCheck /><div><b>{risk.reconciliationClear ? 'Execution gate is clear' : 'Execution gate is blocked'}</b><span>{risk.reconciliationClear ? 'Reconciliation and startup checks permit evaluated Simulation activity.' : 'A critical discrepancy prevents new autonomous risk.'}</span></div><strong>{risk.reconciliationClear ? 'ARMED' : 'HALTED'}</strong></div>
    <section className="risk-kpi-grid">{Object.entries(risk.utilization).map(([key, item]) => { const threshold = 'limit' in item ? item.limit : item.minimum; return <article className="panel" key={key}><span>{key.replace(/([A-Z])/g, ' $1')}</span><strong>{money(item.current, 0)}</strong><small>{'limit' in item ? `of ${money(item.limit, 0)} limit` : `minimum ${money(item.minimum, 0)}`}</small><div><i style={{ width: `${Math.min(100, item.current / (threshold || 1) * 100)}%` }} /></div></article>; })}</section>
    <section className="risk-columns"><article className="panel"><PanelHead eyebrow="TICKER CONCENTRATION" title="Account ownership across strategies" /><div className="concentration-list">{risk.tickerConcentrations.map((item) => <div key={item.symbol}><span><b>{item.symbol}</b><small>{money(item.value, 0)}</small></span><div><i style={{ width: `${Math.min(100, item.percent / Number(risk.config.maxTickerExposurePercent) * 100)}%` }} /></div><strong>{item.percent.toFixed(1)}% <small>/ {text(risk.config.maxTickerExposurePercent)}%</small></strong></div>)}</div></article><article className="panel"><PanelHead eyebrow="SECTOR CONCENTRATION" title="Combined broker exposure" /><div className="concentration-list">{risk.sectorConcentrations.map((item) => <div key={item.sector}><span><b>{item.sector}</b><small>{money(item.value, 0)}</small></span><div><i style={{ width: `${Math.min(100, item.percent / Number(risk.config.maxSectorExposurePercent) * 100)}%` }} /></div><strong>{item.percent.toFixed(1)}% <small>/ {text(risk.config.maxSectorExposurePercent)}%</small></strong></div>)}</div></article></section>
    <section className="panel event-table"><PanelHead eyebrow="RISK EVENTS" title="Recent violations + rejections" /><div className="data-table risks"><div className="table-head"><span>Time</span><span>Severity</span><span>Rule</span><span>Reason</span></div>{risk.events.slice(0, 30).map((event, index) => <div key={text(event.id) || index}><time>{dateTime(event.created_at)}</time><span className={`tag ${text(event.severity).toLowerCase()}`}>{text(event.severity)}</span><b>{text(event.code)}</b><small>{text(event.message)}</small></div>)}</div></section>
    {editing && <GlobalRiskEditor config={editing} setConfig={setEditing} close={() => setEditing(null)} save={() => void propose(editing)} />}
    {pending && <ConfirmChange change={pending} confirm={() => void confirm()} cancel={() => setPending(null)} />}
  </div>;
}

const globalRiskNumberFields = [
  ['maxTotalExposurePercent', 'Maximum account exposure', '%'], ['minimumReservedCash', 'Minimum reserved cash', '$'],
  ['maxTickerExposurePercent', 'Maximum ticker exposure', '%'], ['maxSectorExposurePercent', 'Maximum sector exposure', '%'],
  ['maxDailyDrawdownPercent', 'Maximum daily drawdown', '%'], ['maxWeeklyDrawdownPercent', 'Maximum weekly drawdown', '%'],
  ['maxOpenPositions', 'Maximum open positions', ''], ['maxNewTradesPerDay', 'Maximum new trades / day', ''],
  ['maxOrderNotional', 'Maximum order notional', '$'], ['maxConsecutiveLosses', 'Losses before suspension', ''],
  ['maxStaleDataAgeSeconds', 'Maximum data age', 'sec'], ['maxReconciliationDiscrepancy', 'Maximum reconciliation difference', '$'],
] as const;
const globalRiskBooleanFields = [
  ['restrictToMarketHours', 'Restrict new trades to market hours'], ['optionsEnabled', 'Options enabled'],
  ['cryptoEnabled', 'Crypto enabled'], ['marginEnabled', 'Margin-like behavior enabled'],
] as const;

function GlobalRiskEditor({ config, setConfig, close, save }: { config: Record<string, number | boolean>; setConfig: (value: Record<string, number | boolean>) => void; close: () => void; save: () => void }) {
  return <div className="modal-backdrop"><section className="modal risk-editor-modal"><header><div><p className="eyebrow">IMMUTABLE AUTHORITY BOUNDARY</p><h2>Edit global hard limits</h2></div><button className="icon-button" onClick={close}><X /></button></header><p>Changes require a separate confirmation and become audit events. Agents cannot modify these limits.</p><div className="risk-editor-grid">{globalRiskNumberFields.map(([key, label, unit]) => <NumberField key={key} label={label} value={Number(config[key])} prefix={unit === '$' ? '$' : undefined} suffix={unit !== '$' && unit ? unit : undefined} onChange={(value) => setConfig({ ...config, [key]: value })} />)}</div><div className="risk-toggle-grid">{globalRiskBooleanFields.map(([key, label]) => <label className="toggle-row" key={key}><input type="checkbox" checked={Boolean(config[key])} onChange={(event) => setConfig({ ...config, [key]: event.target.checked })} /><span><b>{label}</b><small>Deterministically enforced in the execution gate.</small></span></label>)}</div><footer><button className="button secondary" onClick={close}>Discard</button><button className="button primary" onClick={save}>Review change</button></footer></section></div>;
}

export function PerformanceView({ notify }: Shared) { const [data, setData] = useState<{ snapshots: Array<Record<string, unknown>>; comparison: Array<Record<string, unknown>>; disclaimer: string } | null>(null); useEffect(() => { api<typeof data>('/api/performance').then(setData).catch((cause) => notify(cause instanceof Error ? cause.message : String(cause), 'danger')); }, []); if (!data) return <Loading />; const groups = data.snapshots.reduce<Record<string, Array<Record<string, unknown>>>>((result, item) => { const key = text(item.strategyId); (result[key] ??= []).push(item); return result; }, {}); const palette = ['#d18a52', '#7693b5', '#d8ad62']; return <div className="page"><PageTitle eyebrow="EXPERIMENT PLATFORM" title="Strategy performance" body="Compare mandates without treating simulation output as evidence of future returns." /><div className="disclaimer"><AlertTriangle />{data.disclaimer}</div><section className="panel performance-chart"><PanelHead eyebrow="STRATEGY EQUITY CURVES" title="30-day simulation history" /><div className="chart-stage">{Object.entries(groups).map(([id, points], index) => <div className="curve-row" key={id}><span style={{ color: palette[index] }}>{id.replaceAll('-', ' ')}</span><div>{points.map((point, pointIndex) => { const equity = Number(point.equity); const first = Number(points[0]?.equity ?? equity); return <i key={pointIndex} style={{ height: `${45 + (equity - first) / Math.max(1, first) * 1000}%`, background: palette[index] }} title={`${dateTime(point.createdAt)} · ${money(equity)}`} />; })}</div><b>{money(Number(points.at(-1)?.equity ?? 0), 0)}</b></div>)}</div></section><section className="comparison-grid">{data.comparison.map((item, index) => <article className={`panel tone-${index}`} key={text(item.strategyId)}><header><span className="strategy-monogram">{index === 0 ? 'D' : index === 1 ? 'G' : 'L'}</span><h3>{text(item.name)}</h3></header><dl><div><dt>Return</dt><dd className={Number(item.returnPercent) >= 0 ? 'positive' : 'negative'}>{percent(Number(item.returnPercent))}</dd></div><div><dt>Realized P/L</dt><dd>{money(Number(item.realizedPnl))}</dd></div><div><dt>Win rate</dt><dd>{Number(item.winRate).toFixed(1)}%</dd></div><div><dt>Trades</dt><dd>{text(item.trades)}</dd></div><div><dt>Turnover</dt><dd>{money(Number(item.turnover), 0)}</dd></div></dl></article>)}</section></div>; }

export function ReconciliationView({ dashboard, refresh, notify }: Shared) {
  const [data, setData] = useState<Record<string, unknown> | null>(null); const [busy, setBusy] = useState(false); const [attributions, setAttributions] = useState<Record<string, string>>({});
  const load = async () => setData(await api<Record<string, unknown>>('/api/reconciliation')); useEffect(() => { void load(); }, []);
  const run = async () => { setBusy(true); try { const result = await post<{ clear: boolean }>('/api/reconciliation/run', {}); notify(result.clear ? 'Ledger and simulated broker state reconcile.' : 'Discrepancies detected; autonomy halted.', result.clear ? 'success' : 'danger'); await Promise.all([load(), refresh()]); } finally { setBusy(false); } };
  const resolveEvent = async (eventId: string, resolution: 'ACKNOWLEDGE_EXTERNAL' | 'REVERSE_AT_BROKER' | 'ATTRIBUTE_TO_STRATEGY') => { const strategyId = attributions[eventId]; const description = resolution === 'ATTRIBUTE_TO_STRATEGY' ? `attribute this manual addition to ${dashboard.strategies.find((item) => item.id === strategyId)?.name ?? 'the selected strategy'}` : resolution === 'ACKNOWLEDGE_EXTERNAL' ? 'classify this as external/manual activity' : 'confirm that the broker-side reversal has already been completed'; if (!window.confirm(`Confirm you want to ${description}. This resolution is audited.`)) return; try { await post(`/api/reconciliation/${eventId}/resolve`, { resolution, strategyId: resolution === 'ATTRIBUTE_TO_STRATEGY' ? strategyId : undefined }); notify('Reconciliation resolution committed and audited.'); await Promise.all([load(), refresh()]); } catch (cause) { notify(cause instanceof Error ? cause.message : String(cause), 'danger'); } };
  if (!data) return <Loading />; const events = data.events as Array<Record<string, unknown>>; const internal = data.internalPositions as Array<Record<string, unknown>>; const broker = data.brokerPositions as Array<Record<string, unknown>>;
  return <div className="page"><PageTitle eyebrow="ACCOUNT INTEGRITY" title="Reconciliation" body="Internal strategy ownership is compared against aggregate broker truth. Meaningful differences are never silently repaired." actions={<button className="button primary" onClick={() => void run()} disabled={busy}>{busy ? <RefreshCw className="spin" /> : <Scale />} Reconcile now</button>} /><div className={`risk-state ${data.clear ? 'clear' : 'blocked'}`}><Scale /><div><b>{data.clear ? 'Ledger matches broker snapshot' : 'Critical mismatches are open'}</b><span>Last run {dateTime(data.lastRunAt)}</span></div><strong>{data.clear ? 'CLEAR' : 'BLOCKED'}</strong></div><section className="recon-grid"><article className="panel"><PanelHead eyebrow="INTERNAL LEDGER" title="Aggregate virtual ownership" /><PositionCompact rows={internal} quantityKey="quantity" /></article><article className="panel"><PanelHead eyebrow="BROKER SNAPSHOT" title="Robinhood / simulation truth" /><PositionCompact rows={broker} quantityKey="quantity" /></article></section><section className="panel event-table"><PanelHead eyebrow="DISCREPANCY QUEUE" title="Manual review required" /><div className="data-table recon"><div className="table-head"><span>Status</span><span>Kind</span><span>Symbol</span><span>Internal</span><span>Broker</span><span>Difference</span><span>Confirmed resolution</span></div>{events.map((event, index) => <div key={text(event.id) || index}><span className={`tag ${text(event.status).toLowerCase()}`}>{text(event.status)}</span><b>{text(event.kind)}</b><b>{text(event.symbol)}</b><span>{text(event.internal_value)}</span><span>{text(event.broker_value)}</span><strong>{text(event.difference)}</strong>{event.status === 'OPEN' ? <div className="recon-actions"><select value={attributions[text(event.id)] ?? dashboard.strategies[0]?.id ?? ''} onChange={(change) => setAttributions({ ...attributions, [text(event.id)]: change.target.value })}>{dashboard.strategies.map((strategy) => <option key={strategy.id} value={strategy.id}>{strategy.name}</option>)}</select><button className="text-button" onClick={() => void resolveEvent(text(event.id), 'ATTRIBUTE_TO_STRATEGY')}>Attribute</button><button className="text-button" onClick={() => void resolveEvent(text(event.id), 'ACKNOWLEDGE_EXTERNAL')}>External</button><button className="text-button danger" onClick={() => void resolveEvent(text(event.id), 'REVERSE_AT_BROKER')}>Reversed</button></div> : <small>Resolved</small>}</div>)}{!events.length && <Empty icon={ShieldCheck} title="No discrepancies recorded" body="Run reconciliation to compare current state." />}</div></section></div>;
}
function PositionCompact({ rows, quantityKey }: { rows: Array<Record<string, unknown>>; quantityKey: string }) { return <div className="position-compact">{rows.map((row, index) => <div key={`${text(row.symbol)}-${index}`}><b>{text(row.symbol)}</b><span>{Number(row[quantityKey] ?? 0).toFixed(6)} shares</span><small>{row.marketValue !== undefined ? money(Number(row.marketValue)) : row.average_cost !== undefined ? `avg ${money(Number(row.average_cost))}` : ''}</small></div>)}{!rows.length && <Empty icon={Database} title="No positions" body="The account is currently in cash." />}</div>; }

export function ActivityView({ notify }: Shared) {
  type ActivityData = { audit: Array<Record<string, unknown>>; risks: Array<Record<string, unknown>>; orders: Array<Record<string, unknown>>; briefs: Array<Record<string, unknown>> };
  const [data, setData] = useState<ActivityData | null>(null); const [tab, setTab] = useState<keyof ActivityData>('audit'); const [generating, setGenerating] = useState(false);
  const load = async () => { const [activity, reports] = await Promise.all([api<Omit<ActivityData, 'briefs'>>('/api/activity'), api<{ briefs: Array<Record<string, unknown>> }>('/api/briefs')]); setData({ ...activity, briefs: reports.briefs }); };
  useEffect(() => { load().catch((cause) => notify(cause instanceof Error ? cause.message : String(cause), 'danger')); }, []);
  const generate = async () => { setGenerating(true); try { await post('/api/briefs/generate', {}); await load(); notify('Daily operating brief generated and persisted.'); } finally { setGenerating(false); } };
  if (!data) return <Loading />; const rows = data[tab];
  return <div className="page"><PageTitle eyebrow="IMMUTABLE OPERATING RECORD" title="Activity + audit" body="Sensitive changes, fills, rejections, reconciliations, reports, and failures remain visible." actions={tab === 'briefs' ? <button className="button primary" disabled={generating} onClick={() => void generate()}>{generating ? <RefreshCw className="spin" /> : <FileClock />} Generate today's brief</button> : undefined} /><div className="tabs"><button className={tab === 'audit' ? 'active' : ''} onClick={() => setTab('audit')}>Audit events</button><button className={tab === 'risks' ? 'active' : ''} onClick={() => setTab('risks')}>Risk events</button><button className={tab === 'orders' ? 'active' : ''} onClick={() => setTab('orders')}>Orders</button><button className={tab === 'briefs' ? 'active' : ''} onClick={() => setTab('briefs')}>Daily briefs</button></div><section className="panel timeline">{rows.map((row, index) => { const content = row.content as Record<string, unknown> | undefined; return <article key={text(row.id) || index}><span className={`timeline-icon ${tab}`}>{tab === 'audit' ? <FileClock /> : tab === 'risks' ? <AlertTriangle /> : tab === 'orders' ? <CircleDollarSign /> : <BrainCircuit />}</span><div><header><b>{tab === 'briefs' ? `Daily brief · ${text(row.reportDate)}` : text(row.action ?? row.code ?? `${row.side} ${row.symbol}`)}</b><time>{dateTime(row.createdAt ?? row.created_at)}</time></header><p>{tab === 'briefs' ? `${text(content?.simulationLabel ?? content?.mode)} · ${Array.isArray(content?.trades) ? content.trades.length : 0} trades · ${Array.isArray(content?.openRisks) ? content.openRisks.length : 0} open risks` : text(row.message ?? row.entityType ?? row.status)}</p><small>{tab === 'briefs' ? 'Persisted account, strategy, decision, risk, trade, and next-evaluation summary' : text(row.actor ?? row.scope ?? row.id)}</small></div></article>; })}{!rows.length && <Empty icon={FileClock} title="No records" body={tab === 'briefs' ? 'Generate a persisted daily operating brief.' : 'Activity will appear here.'} />}</section></div>;
}

export function SettingsView({ dashboard, refresh, notify }: Shared) { const [robinhood, setRobinhood] = useState<Record<string, unknown> | null>(null); const [busy, setBusy] = useState(false); const [maintenance, setMaintenance] = useState(dashboard.maintenance); const [codexReasoning, setCodexReasoning] = useState(false); useEffect(() => { api<{ codexReasoningEnabled: boolean }>('/api/system/settings').then((settings) => setCodexReasoning(settings.codexReasoningEnabled)).catch(() => undefined); }, []); const discover = async () => { setBusy(true); try { setRobinhood(await api<Record<string, unknown>>('/api/robinhood/status')); } finally { setBusy(false); } }; const changeMode = async (mode: string) => { const confirmation = mode === 'LIVE' ? window.prompt('Type ENABLE LIVE TRADING to confirm. Environment gates, MCP auth, and reconciliation must also pass.') ?? '' : undefined; try { await post('/api/system/mode', { mode, confirmation }); notify(`Operating mode changed to ${mode}.`); await refresh(); } catch (cause) { notify(cause instanceof Error ? cause.message : String(cause), 'danger'); } }; return <div className="page"><PageTitle eyebrow="OPERATIONS + CONNECTIONS" title="System settings" body="Runtime-editable strategy settings live in the database; environment values are reserved for deployment and secrets." /><section className="settings-grid"><article className="panel"><PanelHead eyebrow="OPERATING MODE" title="Execution boundary" /><div className="mode-options">{(['SIMULATION', 'READ_ONLY', 'LIVE'] as const).map((mode) => <button key={mode} className={dashboard.mode === mode ? 'active' : ''} onClick={() => void changeMode(mode)}><span className={`mode-radio ${mode.toLowerCase()}`} /><div><b>{mode.replace('_', ' ')}</b><small>{mode === 'SIMULATION' ? 'Internal fills only; broker optional' : mode === 'READ_ONLY' ? 'Official broker reads; no placement' : 'Real orders after every independent gate'}</small></div>{dashboard.mode === mode && <Check />}</button>)}</div><div className="live-warning"><AlertTriangle /><p><b>LIVE is intentionally difficult.</b> It requires two environment variables, an exact admin phrase, clear reconciliation, authenticated official Robinhood MCP, and a database confirmation that emergency stop revokes.</p></div></article><article className="panel"><PanelHead eyebrow="ROBINHOOD TRADING MCP" title="Official broker connection" action={<button className="button secondary" disabled={busy} onClick={() => void discover()}>{busy ? <RefreshCw className="spin" /> : <Network />} Inspect</button>} />{robinhood ? <div className="connection-state"><span className={robinhood.authenticated ? 'connected' : 'disconnected'}>{robinhood.authenticated ? <ShieldCheck /> : <WifiOff />}</span><div><h3>{robinhood.authenticated ? 'Authenticated' : robinhood.configured ? 'Configured, authentication required' : 'Not configured'}</h3><p>{text(robinhood.limitation)}</p></div><div className="capability-list">{Array.isArray(robinhood.capabilities) && robinhood.capabilities.map((capability) => { const item = capability as Record<string, unknown>; return <span key={text(item.name)}><b>{text(item.category)}</b>{text(item.name)}</span>; })}</div></div> : <Empty icon={Network} title="Connection not inspected" body="Capability discovery is read-only and never places or previews an order." />}<code className="command">codex mcp add robinhood-trading --url https://agent.robinhood.com/mcp/trading</code></article><article className="panel"><PanelHead eyebrow="AUTONOMY SERVICES" title="Reasoning + maintenance" /><div className="settings-toggles"><label className="toggle-row big-toggle"><input type="checkbox" checked={codexReasoning} onChange={async (event) => { const enabled = event.target.checked; setCodexReasoning(enabled); await post('/api/system/codex-reasoning', { enabled }); notify(enabled ? 'Scheduled/event-driven Codex reasoning enabled.' : 'Scheduled/event-driven Codex reasoning disabled.'); }} /><span><b>Codex for queued reviews</b><small>Watcher events stay mechanical; only shortlisted events may invoke Codex. Analysis still cannot bypass risk.</small></span></label><label className="toggle-row big-toggle"><input type="checkbox" checked={maintenance} onChange={async (event) => { const enabled = event.target.checked; setMaintenance(enabled); await post('/api/system/maintenance', { enabled }); notify(enabled ? 'Maintenance mode enabled.' : 'Maintenance mode disabled.'); await refresh(); }} /><span><b>Maintenance mode</b><small>Blocks new autonomous orders while watchers and account observation continue.</small></span></label></div></article><article className="panel"><PanelHead eyebrow="DEPLOYMENT POSTURE" title="Private by design" /><div className="posture-list"><div><ShieldCheck /><span><b>Bind locally by default</b><small>Use Tailscale for remote dashboard access.</small></span></div><div><LockKeyhole /><span><b>Credentials stay external</b><small>OAuth and MCP artifacts remain Codex-managed.</small></span></div><div><Database /><span><b>SQLite WAL + backups</b><small>Use USB SSD for continuously written Pi data.</small></span></div></div></article></section></div>; }

function PageTitle({ eyebrow, title, body, actions }: { eyebrow: string; title: string; body: string; actions?: React.ReactNode }) { return <header className="page-title"><div><p className="eyebrow">{eyebrow}</p><h2>{title}</h2><p>{body}</p></div>{actions}</header>; }
function Loading() { return <div className="page loading"><RefreshCw className="spin" /><p>Loading authoritative state…</p></div>; }
